export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-pya-0001", "section": "service", "who": "reader", "text": "В ЧЕТВЕРТОК СВЕТЛЫЯ СЕДМИЦЫ ВЕЧЕРА Пое́м настоя́щее после́дование, бы́вшее от господи́на Ники́фора Калли́ста Ксанфопу́ла. На Пресвяту́ю Госпожу́ Влады́чицу Богоро́дицу Живоприе́мный Исто́чник. Не бо обрето́хом в Ти́пице сицева́го после́дования, но положи́ся любве́ ра́ди Пресвяты́я Богоро́дицы. По 9-м часе, во светильничном, облачится настоятель во всю священную одежду. И став пред святою трапезою с кадильницею, знаменует крестовидно, и возглашает глаголя:"},
  {"id": "cu-pya-0002", "section": "service", "who": "reader", "text": "Благослове́н Бог наш всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-pya-0003", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-pya-0004", "section": "service", "who": "reader", "text": "Ами́нь."},
  {"id": "cu-pya-0005", "section": "service", "who": "rubric", "text": "И той начинает:"},
  {"id": "cu-pya-0006", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0007", "section": "service", "who": "rubric", "text": "Трижды. И мы тойжде отвещаем трижды."},
  {"id": "cu-pya-0008", "section": "service", "who": "reader", "text": "И глаголет настоятель преждереченныя стихи: Первый стих:"},
  {"id": "cu-pya-0009", "section": "service", "who": "reader", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pya-0010", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь:"},
  {"id": "cu-pya-0011", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых:"},
  {"id": "cu-pya-0012", "section": "service", "who": "rubric", "text": "Весь по единожды."},
  {"id": "cu-pya-0013", "section": "service", "who": "rubric", "text": "Вторый стих:"},
  {"id": "cu-pya-0014", "section": "service", "who": "reader", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pya-0015", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-pya-0016", "section": "service", "who": "reader", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pya-0017", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0018", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pya-0019", "section": "service", "who": "reader", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pya-0020", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0021", "section": "service", "who": "reader", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pya-0022", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0023", "section": "service", "who": "reader", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pya-0024", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0025", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-pya-0026", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-pya-0027", "section": "service", "who": "reader", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0028", "section": "service", "who": "rubric", "text": "Таже ектениа великая от диакона:"},
  {"id": "cu-pya-0029", "section": "service", "who": "deacon", "text": "Ми́ром Го́споду помо́лимся."},
  {"id": "cu-pya-0030", "section": "service", "who": "rubric", "text": "Подобает ведати, яко по внегда начати иерею, кадит святую трапезу по обычаю и весь олтарь, вечер, на"},
  {"id": "cu-pya-0031", "section": "service", "who": "deacon", "text": "Го́споди воззва́х:"},
  {"id": "cu-pya-0032", "section": "service", "who": "rubric", "text": "на Утрени, в начале канона исходит и кадит храм и лики и братию по обыкновенному чину."},
  {"id": "cu-pya-0033", "section": "service", "who": "choir", "text": "На Го́споди воззва́х: поставим стихов 10. И поем стихиры воскресны осмогласника 6, глас 6. Стих:"},
  {"id": "cu-pya-0034", "section": "service", "who": "choir", "text": "Изведи́ из темни́цы ду́шу мою́, / испове́датися И́мене Твоему́."},
  {"id": "cu-pya-0035", "section": "service", "who": "choir", "text": "Побе́ду име́я, Христе́, ю́же на а́да, / на Крест возше́л еси́: / да во тьме сме́рти седя́щия воскреси́ши с Собо́ю, / И́же в ме́ртвых Свобо́дь, / Источа́яй живо́т от Своего́ све́та, / Всеси́льне Спа́се, поми́луй нас. Стих:"},
  {"id": "cu-pya-0036", "section": "service", "who": "choir", "text": "Мене́ ждут пра́ведницы, / до́ндеже возда́си мне."},
  {"id": "cu-pya-0037", "section": "service", "who": "choir", "text": "Днесь Христо́с смерть попра́в, / я́коже рече́, воскре́се, / и ра́дование мiрови дарова́, / да вси взыва́юще, песнь та́ко рцем: / Исто́чниче жи́зни, Непристу́пный Све́те, / Всеси́льне Спа́се, поми́луй нас. Стих:"},
  {"id": "cu-pya-0038", "section": "service", "who": "choir", "text": "Из глубины́ воззва́х к Тебе́, Го́споди, / Го́споди, услы́ши глас мой."},
  {"id": "cu-pya-0039", "section": "service", "who": "choir", "text": "Тебе́, Го́споди, Су́щаго по всей тва́ри, / гре́шнии ка́мо бежи́м? / На Небеси́ Сам живе́ши, / во а́де попра́л еси́ смерть. / Во глубины́ морски́я? / Та́мо рука́ Твоя́, Влады́ко. / К Тебе́ прибега́ем, / Тебе́ припа́дающе мо́лимся: / Воскресы́й из ме́ртвых, поми́луй нас."},
  {"id": "cu-pya-0040", "section": "service", "who": "choir", "text": "Ины стихиры восточны (Анатолиевы), глас тойже. Стих:"},
  {"id": "cu-pya-0041", "section": "service", "who": "choir", "text": "Да бу́дут у́ши Твои́ / вне́млюще гла́су моле́ния моего́."},
  {"id": "cu-pya-0042", "section": "service", "who": "choir", "text": "Кресто́м Твои́м, Христе́, хва́лимся, / и воскресе́ние Твое́ пое́м и сла́вим: / Ты бо еси́ Бог наш, / ра́зве Тебе́ ина́го не ве́мы. Стих:"},
  {"id": "cu-pya-0043", "section": "service", "who": "choir", "text": "А́ще беззако́ния на́зриши, Го́споди, Го́споди, кто постои́т; / я́ко у Тебе́ очище́ние есть."},
  {"id": "cu-pya-0044", "section": "service", "who": "choir", "text": "Вы́ну благословя́ще Го́спода, / пое́м воскресе́ние Его́: / Крест бо Претерпе́в, / сме́ртию смерть погуби́. Стих:"},
  {"id": "cu-pya-0045", "section": "service", "who": "choir", "text": "И́мене ра́ди Твоего́ потерпе́х Тя, Го́споди, потерпе́ душа́ моя́ в сло́во Твое́, / упова́ душа́ моя́ на Го́спода."},
  {"id": "cu-pya-0046", "section": "service", "who": "choir", "text": "Сла́ва си́ле Твое́й, Го́споди, / я́ко упраздни́л еси́ держа́ву иму́щаго сме́рти: / обнови́л еси́ нас Кресто́м Твои́м, / да́руя нам живо́т и нетле́ние."},
  {"id": "cu-pya-0047", "section": "service", "who": "choir", "text": "Таже стихиры Живоприемнаго Источника, глас тойже. Подобен: Все возложше: Стих:"},
  {"id": "cu-pya-0048", "section": "service", "who": "choir", "text": "От стра́жи у́тренния до но́щи, от стра́жи у́тренния, / да упова́ет Изра́иль на Го́спода."},
  {"id": "cu-pya-0049", "section": "service", "who": "choir", "text": "Стра́нная и пресла́вная небе́с Влады́ка / на Тебе́ соверша́ше изнача́ла, Всенепоро́чная; / и́бо свы́ше я́вственно ука́ну, / я́коже дождь во утро́бе Твое́й, Богоневе́сто, / исто́чник Тя показу́я все благо́е вре́ющий, / оби́лие же исцеле́ний, / благодея́ния источа́ющий всем незави́стно, / тре́бующим кре́пости душ, и здра́вия телесе́, / водо́ю благода́ти. Стих:"},
  {"id": "cu-pya-0050", "section": "service", "who": "choir", "text": "Я́ко у Го́спода ми́лость, и мно́гое у Него́ избавле́ние, и Той изба́вит Изра́иля от всех беззако́ний eго́."},
  {"id": "cu-pya-0051", "section": "service", "who": "choir", "text": "Ма́нну Тя небе́сную, / и рая́ Де́во исто́чник боже́ственный / имену́ю, Влады́чице, прии́скренне; / земли́ бо тече́ ток, / и благода́ть исто́чника Твоего́ четвероча́стие ея́ покрыва́ющая, / стра́нными чудесы́ всегда́, / и всем проси́мая быва́ет вода́ пие́мая. / Те́мже веселя́щеся христоимени́тии, притека́ем ве́рно, / святы́ню че́рплюще всегда́ сладкото́чную. Стих:"},
  {"id": "cu-pya-0052", "section": "service", "who": "choir", "text": "Хвали́те Го́спода вси язы́цы, похвали́те Его́ вси лю́дие."},
  {"id": "cu-pya-0053", "section": "service", "who": "choir", "text": "Струи́ исцеле́ний источа́еши, Де́во, / ве́рно притека́ющим исто́чнику Твоему́ всегда́, Богоневе́сто; / ту́не бо излива́еши, / оби́льно и бога́тно неду́гующим исцеле́ния; / слепы́я ви́дящия явля́еши я́сно, / приступа́ющия к Тебе́; / хро́мыя мно́гия испра́вила еси́, / и разсла́бленныя стягну́ла еси́, / умерщвле́на же оживи́ла еси́ возлия́нием трегу́бым, / наводне́нных и злоды́шущих стра́сти исцели́ла еси́. Стих:"},
  {"id": "cu-pya-0054", "section": "service", "who": "choir", "text": "Я́ко утверди́ся ми́лость Его́ на нас, и и́стина Госпо́дня пребыва́ет во век."},
  {"id": "cu-pya-0055", "section": "service", "who": "rubric", "text": "И повторяем первую стихиру:"},
  {"id": "cu-pya-0056", "section": "service", "who": "choir", "text": "Стра́нная и пресла́вная небе́с, Влады́ка, / на Тебе́ соверша́ше изнача́ла, Всенепоро́чная; / и́бо свы́ше я́вственно ука́ну, / я́коже дождь во утро́бе Твое́й, Богоневе́сто, / исто́чник Тя показу́я все благо́е вре́ющий, / оби́лие же исцеле́ний, / благодея́ния источа́ющий всем незави́стно, / тре́бующим кре́пости душ, и здра́вия телесе́, / водо́ю благода́ти."},
  {"id": "cu-pya-0057", "section": "service", "who": "choir", "text": "Слава, глас 6: Кто возглаго́лет си́лы твоя́, Исто́чниче, / и́же неистоща́емыми чудесы́ изоби́луяй, / мно́гая и па́че естества́ содева́еши исцеле́ньми? / О́ле вели́чий, я́же всем излива́еши! / Не то́кмо бо боле́зни неудо́бныя отгна́ла еси́ / притека́ющих с любо́вию, / но и душе́вныя стра́сти измыва́еши очища́ющи, Всенескве́рная, / всем подаю́щи ве́лию ми́лость."},
  {"id": "cu-pya-0058", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Кто Тебе́ не ублажи́т, Пресвята́я Де́во? / Кто ли не воспое́т Твоего́ Пречи́стаго Рождества́? / Безле́тно бо от Отца́ Возсия́вый Сын Единоро́дный, / То́йже от Тебе́, Чи́стыя, про́йде, / неизрече́нно вопло́щься, / естество́м Бог сый, / и естество́м быв Челове́к нас ра́ди, / не во двою́ лицу́ Разделя́емый, / но во Двою́ Естеству́ несли́тно Познава́емый. / Того́ моли́, Чи́стая, Всеблаже́нная, / поми́ловатися душа́м на́шим."},
  {"id": "cu-pya-0059", "section": "service", "who": "choir", "text": "Вход с кадилом. Све́те ти́хий:"},
  {"id": "cu-pya-0060", "section": "service", "who": "rubric", "text": "Прокимен, глас 7:"},
  {"id": "cu-pya-0061", "section": "service", "who": "choir", "text": "Возлюблю́ Тя, Го́споди, кре́посте моя́, / Госпо́дь утверже́ние мое́. Стих:"},
  {"id": "cu-pya-0062", "section": "service", "who": "choir", "text": "Бог мой, помо́щник мой, и упова́ю на Него́. Стих:"},
  {"id": "cu-pya-0063", "section": "service", "who": "choir", "text": "Хваля́ призову́ Го́спода, и от враг мои́х спасу́ся. Стих:"},
  {"id": "cu-pya-0064", "section": "service", "who": "choir", "text": "Услы́ша от хра́ма свята́го Своего́ глас мой. Таже:"},
  {"id": "cu-pya-0065", "section": "service", "who": "choir", "text": "Возлюблю́ Тя, Го́споди, кре́посте моя́, Госпо́дь утверже́ние мое́."},
  {"id": "cu-pya-0066", "section": "service", "who": "choir", "text": "На стиховне стихира воскресна, глас 6, осмогласника:"},
  {"id": "cu-pya-0067", "section": "service", "who": "choir", "text": "Воскресе́ние Твое́, Христе́ Спа́се, / А́нгели пою́т на Небесе́х, / и нас на земли́ сподо́би, / чи́стым се́рдцем / Тебе́ сла́вити."},
  {"id": "cu-pya-0068", "section": "service", "who": "choir", "text": "Таже, настоящия стихиры Богородицы, глас 5. Подобен:"},
  {"id": "cu-pya-0069", "section": "service", "who": "choir", "text": "Ра́дуйся, Живоно́сный Исто́чниче, / по моря́м разлива́яй чудеса́, на всю вселе́нную. / Океа́не у́мный, / Ни́ловы струи́ превосходя́й излива́нием благода́ти. / Силоа́ме вторы́й, во́ду источа́яй, / а́ки от ка́мене пресла́вную, / Иорда́ново же прие́мый де́йство. / Ма́нно спаси́тельная же, я́сно быва́емая, / ко и́щущаго тре́бованию, бога́тая вои́стинну и незави́стная, / Христо́ва Ма́ти Отрокови́це, / излива́ющая мiрови ве́лию ми́лость. Стих:"},
  {"id": "cu-pya-0070", "section": "service", "who": "choir", "text": "Освяти́л есть селе́ние / Свое́ Вы́шний."},
  {"id": "cu-pya-0071", "section": "service", "who": "choir", "text": "Пе́сньми чу́дными ве́рнии, / небе́сный о́блак воспои́м, / ка́плю небе́сную Живода́вца Христа́, / на зе́млю нетле́нно одожди́вшую, / жи́ву ска́чущую, и источа́ющую безсме́ртная; / во́ду боже́ственную, Амвроси́ю, не́ктара, / никогда́же по питии́ истлева́юща, / жа́жду же та́ющую ду́ши отгоня́юща. / От него́же пию́щим разу́мно, / то́ки боже́ственныя предлага́ются от у́мнаго чре́ва, / точа́ща всем благода́ть незави́стную. Стих:"},
  {"id": "cu-pya-0072", "section": "service", "who": "choir", "text": "Ре́чная устремле́ния / веселя́т град Бо́жий."},
  {"id": "cu-pya-0073", "section": "service", "who": "choir", "text": "Ра́дуйся, живоприе́мный исто́чниче, / ве́чно источа́я благода́ти, / лия́ние исцеле́ний, вся́кую неду́гов кре́пость, / немощну́ю и злу́ю отгоня́ющее, / слепы́х воззре́ние, и прокаже́нных боже́ственное очище́ние, / точа́щее неду́гов вся́кое врачевство́, / всем притека́ющим ве́рно к хра́му Твоему́; / вели́кая о́бщая цельба́, / безме́здная вои́стинну и гото́вая, / Ма́ти Христа́ Сло́ва, / источа́ющаго мiрови ве́лию ми́лость."},
  {"id": "cu-pya-0074", "section": "service", "who": "choir", "text": "Слава: глас 5: Востру́бим празднолю́бцы в пе́снех, / воспле́щем в вода́х, и возлику́им ра́дующеся, / ве́чными то́ками живоно́снаго исто́чника; / ца́рие и кня́зи да стека́ются, / и исто́чника благода́ти да че́рплют незави́стно; / цари́ бо спасе́, / на одре́ же содержи́мыя прикоснове́нием возста́ви. / Па́стырие же и вси дождено́сный о́блак, / спаси́тельную во́ду сше́дшеся почерпе́м. / И́же в неду́зех свобожде́ние; / и́же в беда́х, кре́пость; / прохлажде́ние, и́же в жа́жде; / слепи́и о́чи, глуси́и благослы́шание, / злостра́ждущии исцеле́ние; / и́же в сме́ртех, живоно́сную; / вси повсю́ду ве́рным источа́ющую во́ды спасе́ния, / воспле́щуще си́це воззове́м: / присноживы́я то́ки излива́ющая от исто́чника, Чи́стая, / не преста́й, Де́во, всегда́ моля́щися / о рабе́х Твои́х."},
  {"id": "cu-pya-0075", "section": "service", "who": "choir", "text": "И ныне, глас тойже: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0076", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0077", "section": "service", "who": "rubric", "text": "трижды, кроме конца стихиры."},
  {"id": "cu-pya-0078", "section": "service", "who": "rubric", "text": "Таже диакон:"},
  {"id": "cu-pya-0079", "section": "service", "who": "deacon", "text": "Прему́дрость. Мы же:"},
  {"id": "cu-pya-0080", "section": "service", "who": "deacon", "text": "Благослови́. Настоятель:"},
  {"id": "cu-pya-0081", "section": "service", "who": "deacon", "text": "Сый благослове́н Христо́с Бог наш: И мы:"},
  {"id": "cu-pya-0082", "section": "service", "who": "deacon", "text": "Утверди́, Бо́же:"},
  {"id": "cu-pya-0083", "section": "service", "who": "rubric", "text": "Таже настоятель, вместо: Слава Тебе Христе Боже:"},
  {"id": "cu-pya-0084", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы:"},
  {"id": "cu-pya-0085", "section": "service", "who": "deacon", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0086", "section": "service", "who": "rubric", "text": "И абие глаголет отпуст со Крестом:"},
  {"id": "cu-pya-0087", "section": "service", "who": "deacon", "text": "Христо́с воскресы́й из ме́ртвых:"},
  {"id": "cu-pya-0088", "section": "service", "who": "rubric", "text": "И прочее, якоже изъявися в конец Утрени."},
  {"id": "cu-pya-0089", "section": "service", "who": "rubric", "text": "И целуем святыя иконы. И входим в трапезу, и глаголем:"},
  {"id": "cu-pya-0090", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0091", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-pya-0092", "section": "service", "who": "deacon", "text": "Христе́ Бо́же благослови́:"},
  {"id": "cu-pya-0093", "section": "service", "who": "rubric", "text": "По востании же от трапезы, глаголем:"},
  {"id": "cu-pya-0094", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0095", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-pya-0096", "section": "service", "who": "deacon", "text": "С на́ми Бог Своею благодатию:"},
  {"id": "cu-pya-0097", "section": "service", "who": "deacon", "text": "В ПЯТОК СВЕТЛЫЯ СЕДМИЦЫ НА УТРЕНИ"},
  {"id": "cu-pya-0098", "section": "service", "who": "deacon", "text": "Прежде начала, вжигает кандила и свещи параекклисиарх. Таже клеплет в великий кампан, и в прочия. И собравшимся нам во храм, иерей полагает обычный поклон настоятелю, и отходит во святый олтарь, и взем кадильницу стоит пред святою Трапезою, кроме убо священническия одежды, епитрахилий точию возложь сверх мантии, кадит крестообразно, глаголя:"},
  {"id": "cu-pya-0099", "section": "service", "who": "deacon", "text": "Сла́ва Святе́й, и Единосу́щней, и Животворя́щей, и Нераздели́мей Тро́ице, всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-pya-0100", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-pya-0101", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-pya-0102", "section": "service", "who": "choir", "text": "Начинает настоятель, с прочими служители, велегласно настоящий тропарь, во глас 5:"},
  {"id": "cu-pya-0103", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0104", "section": "service", "who": "choir", "text": "И мы тойжде поем подобне, со сладкопением. Поется же сей тропарь трижды от настоятеля, и трижды от нас."},
  {"id": "cu-pya-0105", "section": "service", "who": "choir", "text": "Таже настоятель глаголет стихи: Первый стих:"},
  {"id": "cu-pya-0106", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pya-0107", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь весь по единожды:"},
  {"id": "cu-pya-0108", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: Вторый стих:"},
  {"id": "cu-pya-0109", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pya-0110", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды. Третий стих:"},
  {"id": "cu-pya-0111", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pya-0112", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pya-0113", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pya-0114", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pya-0115", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pya-0116", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pya-0117", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pya-0118", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pya-0119", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-pya-0120", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-pya-0121", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-pya-0122", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0123", "section": "service", "who": "choir", "text": "Таже ектения великая. И по возгласе абие поем канон Пасце со ирмосы на 8, и Богородицы на 6."},
  {"id": "cu-pya-0124", "section": "service", "who": "choir", "text": "Канон, глас 1. Песнь 1. Ирмос:"},
  {"id": "cu-pya-0125", "section": "service", "who": "choir", "text": "Воскресе́ния день, / просвети́мся, лю́дие. / Па́сха, Госпо́дня Па́сха, / от сме́рти бо к жи́зни, / и от земли́ к небеси́, / Христо́с Бог нас преведе́, / побе́дную пою́щия. Припев:"},
  {"id": "cu-pya-0126", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0127", "section": "service", "who": "choir", "text": "Очи́стим чу́вствия, и у́зрим / непристу́пным све́том / Воскресе́ния, Христа́ блиста́ющася, / и ра́дуйтеся, реку́ща, / я́сно да услы́шим, / побе́дную пою́ще. Припев:"},
  {"id": "cu-pya-0128", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0129", "section": "service", "who": "choir", "text": "Небеса́ у́бо досто́йно да веселя́тся, / земля́ же да ра́дуется, / да пра́зднует же мир, / ви́димый же весь и неви́димый: / Христо́с бо воста́, / весе́лие ве́чное."},
  {"id": "cu-pya-0130", "section": "service", "who": "choir", "text": "И канон Богородицы, егоже краестрочие: Никифору Каллисту ту Ксанфопулу. Припев:"},
  {"id": "cu-pya-0131", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0132", "section": "service", "who": "choir", "text": "[Ν] Ны́не источи́ ми, Де́во Богоро́дице исто́чниче, / благода́ть даю́щи Сло́ва, / я́ко да воспою́ Тя, исто́чник, / вре́ющий живо́т и благода́ть ве́рным; / Ты бо ипоста́сное Сло́во источи́ла еси́. Припев:"},
  {"id": "cu-pya-0133", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0134", "section": "service", "who": "choir", "text": "[Ι] Врачевство́ па́че естества́, / храм Твой, Честна́я, / явля́ется всем, Отрокови́це, / от сме́рти бо я́вныя / притека́ющия ве́рныя я́ве возставля́ет, / и всем незави́стную то́чит сла́дость."},
  {"id": "cu-pya-0135", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Κ] Излива́еши с небесе́ неистощи́мо / благода́ти вои́стинну еди́на: / слепе́юща бо твори́ши взира́ти к све́ту, бла́том но́вым, / возгласи́вши свы́ше па́че смы́сла Лео́нови."},
  {"id": "cu-pya-0136", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Η] О́бщее любоче́стие челове́чества Честна́я, / ра́дуйся Мари́е, ра́дуйся; / всех бо Творе́ц на Тя, я́коже ка́пля сни́де я́вственно, / исто́чник Тя безсме́ртен показа́в Богоневе́стная."},
  {"id": "cu-pya-0137", "section": "service", "who": "rubric", "text": "Катавасия оба лика вкупе:"},
  {"id": "cu-pya-0138", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-pya-0139", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0140", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-pya-0141", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое, / не от ка́мене непло́дна чудоде́емое, / но нетле́ния исто́чник / из гро́ба одожди́вша Христа́, / в Не́мже утвержда́емся. Припев:"},
  {"id": "cu-pya-0142", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0143", "section": "service", "who": "choir", "text": "Ны́не вся испо́лнишася све́та, / не́бо же и земля́, и преиспо́дняя: / да пра́зднует у́бо вся тварь / воста́ние Христо́во, / в не́мже утвержда́ется. Припев:"},
  {"id": "cu-pya-0144", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0145", "section": "service", "who": "choir", "text": "Вчера́ спогребо́хся Тебе́ Христе́, / совостаю́ днесь / воскре́сшу Тебе́, / сраспина́хся Тебе́ вчера́, / Сам мя спросла́ви Спа́се во Ца́рствии Твое́м."},
  {"id": "cu-pya-0146", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0147", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0148", "section": "service", "who": "choir", "text": "[Φ] Све́тлый Тя святы́й храм / Влады́ки всех, Отрокови́це вем, / и нетле́ния Исто́чник, / во́ду излива́ющ Христа́, / от Него́же напая́емся. Припев:"},
  {"id": "cu-pya-0149", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0150", "section": "service", "who": "choir", "text": "[Ο] От Твоея́ благода́ти, Влады́чице исто́чниче, / Самоде́ржцу дае́ши исхо́дов происхожде́ние содержи́мо лю́те, / ка́мене подстоя́ние стра́шное, / водо́ю разреши́вшееся."},
  {"id": "cu-pya-0151", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Ρ] Тече́т благода́ть незави́стная / от Тебе́, Богоро́дице Де́во, оби́льно точа́щая, / хроми́и ска́чут о Тебе́, / прокаже́нных очища́ется мно́жество, / и де́мони угнета́ются."},
  {"id": "cu-pya-0152", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Ο] Всем дае́ши исцеле́ние ве́рным, / царе́м, простце́м, ни́щим, / князе́м, убо́гим, бога́тым о́бще, / во́ду излива́яй Исто́чниче / разли́чное исцеле́ние. Катавасия:"},
  {"id": "cu-pya-0153", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое: И тропарь:"},
  {"id": "cu-pya-0154", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0155", "section": "service", "who": "choir", "text": "Таже ектениа."},
  {"id": "cu-pya-0156", "section": "service", "who": "choir", "text": "Таже кондак Пасце, глас 8:"},
  {"id": "cu-pya-0157", "section": "service", "who": "choir", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко победитель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся, / и Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние. Икос:"},
  {"id": "cu-pya-0158", "section": "service", "who": "choir", "text": "Е́же пре́жде со́лнца Со́лнце заше́дшее иногда́ во гроб, / предвари́ша ко у́тру, и́щущия я́ко дне мvроно́сицы де́вы, / и друга́ ко друзе́й вопия́ху: / о други́ни! Прииди́те, воня́ми пома́жем те́ло живоно́сное и погребе́ное, / плоть воскреси́вшаго па́дшаго Ада́ма, лежа́щую во гро́бе. / И́дем, потщи́мся я́коже волсви́, и поклони́мся, / и принесе́м мvра я́ко да́ры, не в пелена́х, но в плащани́це обви́тому, / и пла́чим, и возопии́м: о Влады́ко, воста́ни, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-pya-0159", "section": "service", "who": "choir", "text": "Седален, глас 8. Подобный: Прему́дрости Сло́ва:"},
  {"id": "cu-pya-0160", "section": "service", "who": "choir", "text": "Приснотеку́щий Исто́чник, и живо́тный, / источа́яй струя́ боже́ственный ток, / согла́сно восхва́лим благода́ти прося́ще; / на ки́йждо бо день источа́ет исцеле́ния, / я́ко рек тече́ния показу́яй мале́йшая. / Те́мже по до́лгу приступа́юще с любо́вию, / ве́рно почерпе́м от Исто́чника / неисчерпа́емое здра́вие, вои́стинну безсме́ртное, / ороша́ющее ве́рно благочести́вых сердца́; / устна́ми возопии́м, / Ты еси́ ве́рных утеше́ние."},
  {"id": "cu-pya-0161", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-pya-0162", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи / богоглаго́ливый Авваку́м / да ста́нет с на́ми и пока́жет / светоно́сна А́нгела / я́сно глаго́люща: / днесь спасе́ние ми́ру, / я́ко воскре́се Христо́с, / я́ко всеси́лен. Припев:"},
  {"id": "cu-pya-0163", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0164", "section": "service", "who": "choir", "text": "Му́жеский у́бо пол, / я́ко разве́рзый де́вственную утро́бу, / яви́ся Христо́с, / я́ко челове́к же, / А́гнец нарече́ся, / непоро́чен же, / я́ко невку́сен скве́рны, / на́ша Па́сха, / и я́ко Бог и́стинен / соверше́н рече́ся. Припев:"},
  {"id": "cu-pya-0165", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0166", "section": "service", "who": "choir", "text": "Я́ко единоле́тный а́гнец, / благослове́нный нам вене́ц Христо́с, / во́лею за всех закла́н бысть, / Па́сха чисти́тельная, / и па́ки из гро́ба кра́сное / пра́вды нам возсия́ Со́лнце. Припев:"},
  {"id": "cu-pya-0167", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0168", "section": "service", "who": "choir", "text": "Богооте́ц у́бо Дави́д / пред се́нным ковче́гом скака́ше игра́я, / лю́дие же Бо́жии святи́и, / образо́в сбытие́ зря́ще, / весели́мся Боже́ственне, / я́ко воскре́се Христо́с, / я́ко Всеси́лен."},
  {"id": "cu-pya-0169", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0170", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0171", "section": "service", "who": "choir", "text": "[Υ] Па́че песка́ вои́стинну, и ка́плий дожде́вных, / бы́ша Богоро́дице мно́жества, исто́чника дел Твои́х, / непреста́нно теку́щая на всю зе́млю бога́тно, / и вся́каго боля́ща лю́те / ско́ро исцеля́ющая. Припев:"},
  {"id": "cu-pya-0172", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0173", "section": "service", "who": "choir", "text": "[Κ] На стесне́нный жены́ от карки́на сосе́ц, / вода́ возлива́ется, Де́во, / исто́чника Твоего́, Влады́чице, / и а́бие преста́ша стра́сти смертоно́сныя струе́ю, / и карки́н про́сто изы́ти позна́."},
  {"id": "cu-pya-0174", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Α] Недомы́слимое в Тебе́, / и па́че естества́ соде́янное / есть я́вственно, Богоро́дице, / вода́ бо быва́ет исто́чника Твоего́ исцеле́ние, / неду́гом смертоно́сным проти́вное, / его́же естество́ я́ве / никогда́же ве́дяше."},
  {"id": "cu-pya-0175", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Λ] При́сно умерщвля́ет мя враг / сла́стными прило́ги, / Влады́чице исто́чниче Богоро́дице, не пре́зри, / предвари́ ско́рая по́моще; / сего́ же се́тей мя изба́ви, / да воспою́ Тя, при́сно многопе́тую. Катавасия:"},
  {"id": "cu-pya-0176", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи: И тропарь:"},
  {"id": "cu-pya-0177", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0178", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-pya-0179", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́, / и вме́сто ми́ра песнь принесе́м Влады́це, / и Христа́ у́зрим / пра́вды Со́лнце, / всем жизнь возсия́юща. Припев:"},
  {"id": "cu-pya-0180", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0181", "section": "service", "who": "choir", "text": "Безме́рное Твое́ благоутро́бие, / а́довыми у́зами содержи́мии зря́ще, / к све́ту идя́ху Христе́, / весе́лыми нога́ми, / Па́сху хва́ляще ве́чную. Припев:"},
  {"id": "cu-pya-0182", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0183", "section": "service", "who": "choir", "text": "Присту́пим свещено́снии, / исходя́щу Христу́ из гро́ба, я́ко жениху́, / и спра́зднуем любопра́зднственными чи́нми / Па́сху Бо́жию спаси́тельную."},
  {"id": "cu-pya-0184", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0185", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0186", "section": "service", "who": "choir", "text": "[Λ] Глаго́ланная Де́во Отрокови́це, / исто́чника Твоего́ вои́стинну чудеса́, / ужаса́ют челове́ков помышле́ние; / па́че бо естества́ суть, / вся ве́рныя освяща́ющая. Припев:"},
  {"id": "cu-pya-0187", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0188", "section": "service", "who": "choir", "text": "[Ι] Повествова́ руно́, ма́нна / и Силоа́м, и ка́мень точа́щь, / Соломо́нов притво́р, благода́ть Твою́, / Иорда́нския во́ды, и исто́чник самаряны́ни."},
  {"id": "cu-pya-0189", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Σ] Ка́пли Твоя́, Отрокови́це Де́во, / я́же исто́чника, и ме́ртваго оживи́ша, / па́че сло́ва соде́янное и смы́сла; / вся бо Твоя́, Всечи́стая, / сло́во побежда́ют челове́ческое."},
  {"id": "cu-pya-0190", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Τ] Стра́сти моя́, Отрокови́це, исцели́, / кровотече́ния исто́чник изсуша́ющи, / и лю́тое пла́мене возжже́ние, и здра́вия преложе́ние, / исхо́дов сою́з, и чревотече́ние. Катавасия:"},
  {"id": "cu-pya-0191", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́: И тропарь:"},
  {"id": "cu-pya-0192", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0193", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-pya-0194", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́, / и сокруши́л еси́ вереи́ ве́чныя, / содержа́щия свя́занныя, Христе́, / и тридне́вен, я́ко от ки́та Ио́на, / воскре́сл еси́ от гро́ба. Припев:"},
  {"id": "cu-pya-0195", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0196", "section": "service", "who": "choir", "text": "Сохрани́в це́ла зна́мения Христе́, / воскре́сл еси́ от гро́ба, / ключи́ Де́вы не вреди́вый в рождестве́ Твое́м, / и отве́рзл еси́ нам ра́йския две́ри. Припев:"},
  {"id": "cu-pya-0197", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0198", "section": "service", "who": "choir", "text": "Спа́се мой, / живо́е же и неже́ртвенное заколе́ние, / я́ко Бог Сам Себе́ / во́лею приве́л Отцу́, / совоскреси́л еси́ всеро́днаго Ада́ма, / воскре́с от гро́ба."},
  {"id": "cu-pya-0199", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0200", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0201", "section": "service", "who": "choir", "text": "[Ο] Словеса́ Сло́ва, я́ко вои́стинну исто́чника, / воспева́ем Тя, Чи́стая, / прему́дрости бо глубину́, / я́ко па́че сло́ва ражда́еши, / пове́сивша на возду́се тече́ния, / и зе́млю на воде́. Припев:"},
  {"id": "cu-pya-0202", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0203", "section": "service", "who": "choir", "text": "[Υ] Подшла́ еси́ ле́ствиц несе́ние, / отъе́млющее сокруше́ние и́же та́мо живопи́сцов, / о всесвяты́й исто́чниче! спаса́яй лю́ди / от тру́са до́му па́дшия."},
  {"id": "cu-pya-0204", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Τ] Утро́бы неродя́щия непло́дством пре́жде, / разреша́еши я́ве, / исто́чника Твоего́ струя́ми, / и́бо я́ко роди́вшая Влады́ку всех, / и рожде́ния подае́ши."},
  {"id": "cu-pya-0205", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Ο] Ни сло́во, ни ум, ниже́ язы́к / Твое́ возмо́гут, Чи́стая, Рождество́ похвали́ти, / но немощству́ют в Тебе́, / и облича́ется филосо́фов че́стность, / и ри́торов красота́. Катавасия:"},
  {"id": "cu-pya-0206", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́: И тропарь:"},
  {"id": "cu-pya-0207", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0208", "section": "service", "who": "choir", "text": "Ектениа."},
  {"id": "cu-pya-0209", "section": "service", "who": "choir", "text": "Кондак, глас 8. Подобен: Взбра́нной:"},
  {"id": "cu-pya-0210", "section": "service", "who": "choir", "text": "От неистощи́мыя Ты, исто́чниче богоблагода́тный, / подае́ши ми, точа́щи во́ды Твоея́ благода́ти, / приснотеку́щий па́че сло́ва, / я́ко бо Сло́во ро́ждшая па́че смы́сла, / молю́ Ти ся, ороси́ мя благода́тию, да зову́ Ти: / ра́дуйся, водо́ спаси́тельная. Икос:"},
  {"id": "cu-pya-0211", "section": "service", "who": "choir", "text": "Нескве́рная Богоро́дице, ро́ждшая Сло́во О́тчее, / пре́жде век нетле́нно ро́ждшееся, / разшири́ моя́ уста́, Чи́стая, / спривнося́щи мя к Твоему́ похвале́нию, / я́ко да восхвалю́ Тя, зовы́й исто́чнику Твоему́ сия́:"},
  {"id": "cu-pya-0212", "section": "service", "who": "choir", "text": "Ра́дуйся, исто́чниче ра́дости непреста́емыя; / ра́дуйся, то́че добро́ты неизрече́нныя."},
  {"id": "cu-pya-0213", "section": "service", "who": "choir", "text": "Ра́дуйся, неду́гов разли́чных разреше́ние; ра́дуйся страсте́й вся́ких потопле́ние."},
  {"id": "cu-pya-0214", "section": "service", "who": "choir", "text": "Ра́дуйся струе́ светови́днейшая, здра́вы творя́щая ве́рныя; / ра́дуйся водо́ благода́тнейшая неду́гующим многоразли́чно."},
  {"id": "cu-pya-0215", "section": "service", "who": "choir", "text": "Ра́дуйся ча́ше ма́нны живото́чныя; / ра́дуйся ба́не и не́ктарю богоизлия́нный."},
  {"id": "cu-pya-0216", "section": "service", "who": "choir", "text": "Ра́дуйся водо́, прему́дрости неве́дение отъе́млющая; / ра́дуйся растворе́ние се́рдца, пи́щу боже́ственную излива́ющее."},
  {"id": "cu-pya-0217", "section": "service", "who": "choir", "text": "Ра́дуйся приста́нище неможе́ния источа́ющая; / ра́дуйся пла́мень неду́гования угаша́ющая."},
  {"id": "cu-pya-0218", "section": "service", "who": "choir", "text": "Ра́дуйся водо́ спаси́тельная."},
  {"id": "cu-pya-0219", "section": "service", "who": "choir", "text": "Синаксарь на Пресвятую Госпожу Владычицу Богородицу, Живоприемный Источник. В пято́к Све́тлыя седми́цы, пра́зднуем обновле́ние хра́ма Пресвяты́я и Госпожи́ на́шея Богоро́дицы, имену́емаго живоно́снаго исто́чника. Еще́ же па́мять твори́м изря́дных и па́че естества́ чуде́с бы́вших, во о́ном хра́ме от Богома́тере."},
  {"id": "cu-pya-0220", "section": "service", "who": "choir", "text": "Сей у́бо храм пе́рвее основа́ся от царя́ Льва Вели́каго, и́же и Маке́лл именова́ся. Сей поне́же бя́ше благ и смире́н челове́к, за до́брое свое́ наме́рение и ми́лостивное, е́же имя́ше, пре́жде не́же бы́ти царю́, обрета́яйся во о́ном ме́сте, обре́те еди́наго челове́ка слепа́го, не ви́дяща ка́мо ити́, и взем его́ за ру́ку, ведя́ше. Дости́гшима же обои́ма та́мо близ, иде́же бя́ше сей исто́чник, возжада́ слепы́й, и моля́ше Льва, да ороси́т его́; и́же идя́ во вну́треннее о́ное ле́са, иде́же бя́ше древе́с и насажде́ний разли́чных испо́лнено, иска́ше воды́, и не обрета́яй исто́чника, обраща́шеся а́ки отягча́емь. И слы́шит глас свы́ше глаго́лющь: о Льве! не уныва́й, зане́ вода́, ея́же и́щеши, близ тебе́ есть, и обрати́ся обрести́ ю́. И Лев у́бо обраща́яйся, и ища́й мно́го, не обре́те ея́. И па́ки слы́шит ра́вный пе́рвому глас, и глаго́лет ему́: царю́ Льве, вни́ди во вну́треннюю часть загуще́ннаго сего́ ле́са, и возми́ свои́ма рука́ма от сея́ му́тныя воды́, и исцели́ жа́жду слепа́го, и пома́жи и помраче́нныя его́ о́чи; и а́бие позна́еши, ка́я есмь, и от мно́гаго вре́мене живу́ на сем ме́сте. Лев у́бо сотвори́ я́коже глас повеле́ ему́, и а́бие воззре́ слепы́й."},
  {"id": "cu-pya-0221", "section": "service", "who": "choir", "text": "И по Богома́тере прорече́нию, по ма́ле вре́мени бысть царь Лев: и созда́ та́мо у исто́чника храм пе́рвый, бога́тою руко́ю, я́коже зри́тся днесь. И поне́же быва́ху чудеса́ множа́йшая на вся́кий день, по мно́гих ле́тех Иустиниа́н вели́кий самоде́ржец гре́ческий, поне́же пострада́ зело́ от не́мощи водотру́дия, и обре́те та́мо исцеле́ние свое́, хотя́ да́ти воздая́ние Ма́тери Бо́жией, па́ки созда́ о́ный пе́рвый храм, и сотвори́ и велича́йший и красне́йший, и́же от мно́гих тру́сов внегда́ разсе́деся, последи́ царь Васи́лий Македо́нский, и сын его́ Лев Му́дрый, па́ки созда́ша и испра́виша и́. Во вре́мя их сей исто́чник мно́га чудеса́ де́йствова:"},
  {"id": "cu-pya-0222", "section": "service", "who": "choir", "text": "и вод задержа́ния, и пти́сы, и ины́я тмочи́сленныя стра́сти исцели́: карки́нския стра́сти, и кровотече́ния мно́гих родо́в, и́миже стражда́ху царе́вны и ины́я жены́, и разли́чныя огне́вицы, и ины́я боле́зни, и я́звы неисце́льныя, и непло́дныя разреши́; я́ко и цари́ца Зои́ непло́ды су́щи прия́т дар от сего́ исто́чника, сы́на Константи́на Порфироге́нита. Воскреси́ же и ме́ртваго, и́же бе от Фессали́и, и приходя́ ко свято́му исто́чнику у́мре на пути́. Егда́ же хотя́ше умре́ти, запове́да кора́блеником взя́ти его́ та́мо во храм исто́чника, и возлия́ти на него́ три ка́ди от о́ныя воды́, и тогда́ погребсти́ его́. Е́же творя́ще кора́бленицы, и возлива́юще на него́ во́ду, а́бие воскре́се ме́ртвый. По мно́гом же вре́мени, хотя́ па́сти вели́кий храм о́ный, яви́ся Богоро́дица, и держа́ше его́, до́ндеже изы́де вон все мно́жество люде́й, и никто́же вреди́ся. Та́яжде свята́я вода́ пива́ема, мно́гия бесну́емыя исцели́, и от темни́цы челове́ки свя́занныя разреши́. Исцели́ же и царя́ Льва от каменозая́тия, и жены́ его́ Феофа́ны угаси́ зе́льнейшую огне́вицу. И бра́та его́ Стефа́на разреши́ от пти́сныя не́мощи. Дарова́ же и слух Иоа́нну патриа́рху Иерусали́мскому. Исцели́ еще́ и си́льную огне́вицу Патри́киа Тара́сиа, и ма́тере его́ Магистри́ссы, и сы́на Стилиа́нова исцели́ от водозадержа́ния. И не́кую жену́ и́менем Схи́зину свободи́ от чревоболе́ния. И царя́ Рома́на исцели́, от разреше́ния и связа́ния чре́ва та́яжде вода́, подо́бне и жену́ его́. Призва́нием же то́кмо исцели́ Всесвята́я мона́ха Пе́перин, и ученика́ его́ в Халде́и. Подо́бне и мона́ха Матфе́а, и Меле́тиа, и́хже оболга́ша царю́, свободи́ от гне́ва; Патри́киа же и Протоспафа́риа, и ины́я тмочи́сленныя кто испове́дати мо́жет?"},
  {"id": "cu-pya-0223", "section": "service", "who": "choir", "text": "Несть же пра́ведно не воспомина́ти и исцеле́ния Исхи́ова; ниже́ кий язы́к мо́жет пове́дати, ели́ка чудеса́ та́яжде вода́ де́йствова, и да́же до днесь де́йствует, па́че ка́плей дожде́вных, и па́че звезд небе́сных, и листо́в мно́жества, я́же в на́ша времена́ ви́дехом. Еще́ исцели́ и ины́я смертоно́сныя боле́зни, прока́зы, свербо́ты па́че естества́, и опухле́ния же́нская, и душе́вныя стра́сти мно́гия исцели́, и разли́чныя очны́я боле́зни. Еще́ же исцели́ вара́гга Иоа́нна от воднотрудова́ния, и друга́го вара́гга исцели́ от злых язв, и священномона́ха Ма́рка от о́спы, и каменозая́тия мона́ха Заха́рию. И ина́я мно́жайшая чудеса́, я́же не возмо́жно есть исчи́слити, я́же де́йствова и де́йствует непреста́нно."},
  {"id": "cu-pya-0224", "section": "service", "who": "choir", "text": "Твоея́ Ма́тере моли́твами, Христе́ Бо́же наш поми́луй нас. Ами́нь."},
  {"id": "cu-pya-0225", "section": "service", "who": "choir", "text": "Таже глаголем:"},
  {"id": "cu-pya-0226", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному, / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим: / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию: / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́. [Трижды.]"},
  {"id": "cu-pya-0227", "section": "service", "who": "choir", "text": "Воскре́с Иису́с от гро́ба, / я́коже прорече́, / даде́ нам живо́т ве́чный / и ве́лию ми́лость. [Трижды.]"},
  {"id": "cu-pya-0228", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-pya-0229", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый, / быв Челове́к, / стра́ждет я́ко сме́ртен, / и стра́стию сме́ртное, / в нетле́ния облачи́т благоле́пие, / Еди́н благослове́н / отце́в Бог, и препросла́влен. Припев:"},
  {"id": "cu-pya-0230", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0231", "section": "service", "who": "choir", "text": "Жены́ с ми́ры богому́дрыя в след Тебе́ теча́ху, / Его́же, я́ко ме́ртва, со слеза́ми иска́ху, / поклони́шася ра́дующияся Живо́му Бо́гу, / и Па́сху та́йную / Твои́м, Христе́, ученико́м благовести́ша. Припев:"},
  {"id": "cu-pya-0232", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0233", "section": "service", "who": "choir", "text": "Сме́рти пра́зднуем умерщвле́ние, / а́дово разруше́ние, / ино́го жития́ ве́чнаго нача́ло, / и игра́юще пое́м Вино́внаго, / Еди́наго благослове́ннаго / отце́в Бо́га, и препросла́вленнаго. Припев:"},
  {"id": "cu-pya-0234", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0235", "section": "service", "who": "choir", "text": "Я́ко вои́стинну свяще́нная, / и всепра́зднственная сия́ спаси́тельная нощь, / и светоза́рная, / светоно́снаго дне, / воста́ния су́щи провозве́стница, / в не́йже безле́тный Свет из гро́ба пло́тски всем возсия́."},
  {"id": "cu-pya-0236", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0237", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0238", "section": "service", "who": "choir", "text": "[Υ] Почерпи́те неду́гующии исцеле́ния; / Всечи́стая бо то́чит от боже́ственнаго исто́чника сла́дость и́стинную, / пото́к сла́дости вои́стинну вре́ющий, / те́мже и ве́рою то́ки незави́стныя / поче́рпем вси. Припев:"},
  {"id": "cu-pya-0239", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0240", "section": "service", "who": "choir", "text": "[Ξ] Удивля́ют слы́шащия, Влады́чице, / стра́нная Твоя́ чудеса́, вся ве́рныя: / немы́я бо и глухи́я, я́ко благоглаго́ливыя / показу́ет вода́ Твоя́, / стра́ждущия же лю́те врачу́ет, / и исцеле́ние да́рует."},
  {"id": "cu-pya-0241", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. [Α] Возво́диши от пе́щи скорбе́й, / ороша́ющи вода́ми от стра́ннаго исто́чника, / приступа́ющия к Тебе́, Чи́стая: / карки́нския бо ра́ны свобожда́ется челове́к, / прокаже́нна же исцеля́еши, / и распале́ние угаси́ла еси́."},
  {"id": "cu-pya-0242", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. [Ν] Ю́ноши и отрокови́цы Влады́чицу, / и вси челове́цы ве́рою от души́ восхва́лим све́тло; / сокруше́ния бо гное́виц, и вре́ды лука́вых, / и ото́ки, и разсла́бленнаго исцели́. Катавасия:"},
  {"id": "cu-pya-0243", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый: И тропарь:"},
  {"id": "cu-pya-0244", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0245", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-pya-0246", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день, / Еди́н суббо́т Царь и Госпо́дь, / пра́здников пра́здник / и торжество́ есть торже́ств, / во́ньже благослови́м Христа́ во ве́ки. Припев:"},
  {"id": "cu-pya-0247", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0248", "section": "service", "who": "choir", "text": "Прииди́те, но́ваго виногра́да рожде́ния, / Боже́ственнаго весе́лия, / в наро́читом дни Воскресе́ния, / Ца́рствия Христо́ва приобщи́мся, / пою́ще Его́ / я́ко Бо́га во ве́ки. Припев:"},
  {"id": "cu-pya-0249", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-pya-0250", "section": "service", "who": "choir", "text": "Возведи́ о́крест о́чи твои́, Сио́не, и виждь: / се бо приидо́ша к тебе́, / я́ко богосве́тлая свети́ла, / от за́пада, и се́вера, и мо́ря, / и восто́ка ча́да твоя́, / в тебе́ благословя́щая Христа́ во ве́ки. Припев:"},
  {"id": "cu-pya-0251", "section": "service", "who": "choir", "text": "Пресвята́я Тро́ице, Бо́же наш, сла́ва Тебе́. Троичен:"},
  {"id": "cu-pya-0252", "section": "service", "who": "choir", "text": "О́тче Вседержи́телю, и Сло́ве, и Ду́ше, / треми́ соединя́емое во Ипоста́сех Естество́, / Пресу́щественне и Пребоже́ственне, / в Тя крести́хомся, / и Тя благослови́м во вся ве́ки."},
  {"id": "cu-pya-0253", "section": "service", "who": "choir", "text": "Богородицы подобны: Припев:"},
  {"id": "cu-pya-0254", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0255", "section": "service", "who": "choir", "text": "[Θ] Боже́ственную исто́чник и честну́ю во́ду / излива́ет Твой Де́во; / водны́х бо тече́ние вспяща́ет зело́, / призыва́нием боже́ственным благода́ти. / Те́мже тя почита́ем, исто́чниче, во ве́ки. Припев:"},
  {"id": "cu-pya-0256", "section": "service", "who": "choir", "text": "Пресвята́я Богоро́дице, спаси́ нас."},
  {"id": "cu-pya-0257", "section": "service", "who": "choir", "text": "[Ο] Вси честну́ю живото́чную во́ду / воспои́м му́дренне: / злодыха́ния бо ток по страна́м уставля́ет, / и свобо́дное твори́т происхожде́ние. / О́ле Твои́х чуде́с, / Чи́стая Богороди́тельнице!"},
  {"id": "cu-pya-0258", "section": "service", "who": "choir", "text": "Благослови́м Отца́ и Сы́на и Свята́го Ду́ха, Го́спода."},
  {"id": "cu-pya-0259", "section": "service", "who": "choir", "text": "[Π] Ка́я, Всепе́тая, восхва́лят уста́ / Рождества́ Твоего́ стра́нное? / Но и ум кий бы чуде́с исто́чник изсле́довал, / и сло́во изглаго́лало? / Несть естеству́ кре́пость, Твои́м чуди́тися."},
  {"id": "cu-pya-0260", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-pya-0261", "section": "service", "who": "choir", "text": "[Ο] Вся о Тебе́ сме́рти держа́ва / разори́ся внеза́пу, о Цари́це и Госпоже́, / и́бо Царя́ Безсме́ртнаго, живо́т Ты источи́ла еси́, / во́ду, ма́нну, Христа́ во ве́ки. Катавасия:"},
  {"id": "cu-pya-0262", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день: И тропарь:"},
  {"id": "cu-pya-0263", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-pya-0264", "section": "service", "who": "choir", "text": "Песнь 9."},
  {"id": "cu-pya-0265", "section": "service", "who": "deacon", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца."},
  {"id": "cu-pya-0266", "section": "service", "who": "rubric", "text": "И первый лик ирмос:"},
  {"id": "cu-pya-0267", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-pya-0268", "section": "service", "who": "rubric", "text": "Таже вторый лик поет вторый припев:"},
  {"id": "cu-pya-0269", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-pya-0270", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-pya-0271", "section": "service", "who": "rubric", "text": "Таже первый лик поет:"},
  {"id": "cu-pya-0272", "section": "service", "who": "choir", "text": "Христо́с но́вая Па́сха, / Же́ртва жива́я, / А́гнец Бо́жий, / взе́мляй грехи́ ми́ра."},
  {"id": "cu-pya-0273", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго, / о сладча́йшаго Твоего́ гла́са! / С на́ми бо нело́жно / обеща́лся еси́ бы́ти, / до сконча́ния ве́ка Христе́: / Его́же, ве́рнии, / утвержде́ние наде́жди иму́ще, ра́дуемся."},
  {"id": "cu-pya-0274", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-pya-0275", "section": "service", "who": "rubric", "text": "Таже первый лик поет припев:"},
  {"id": "cu-pya-0276", "section": "service", "who": "choir", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый: / лю́дие, весели́теся. И тропарь:"},
  {"id": "cu-pya-0277", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-pya-0278", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-pya-0279", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pya-0280", "section": "service", "who": "choir", "text": "Возбуди́л еси́ усну́в ме́ртвыя от ве́ка, / ца́рски рыка́вый я́ко от Иу́ды лев. И тропарь:"},
  {"id": "cu-pya-0281", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-pya-0282", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pya-0283", "section": "service", "who": "choir", "text": "Магдали́на Мари́я притече́ ко гро́бу, / и Христа́ ви́девши, / я́ко вертогра́даря вопроша́ше."},
  {"id": "cu-pya-0284", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая, Христе́! / О му́дросте, и Сло́ве Бо́жий, и си́ло! / Подава́й нам и́стее Тебе́ причаща́тися, / в невече́рнем дни Ца́рствия Твоего́."},
  {"id": "cu-pya-0285", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pya-0286", "section": "service", "who": "choir", "text": "А́нгел облиста́яй жена́м вопия́ше: / преста́ните от слез, я́ко Христо́с воскре́се. И тропарь:"},
  {"id": "cu-pya-0287", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pya-0288", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pya-0289", "section": "service", "who": "choir", "text": "Христо́с воскре́се, смерть попра́вый, / и ме́ртвыя воздви́гнувый, / лю́дие весели́теся. И тропарь:"},
  {"id": "cu-pya-0290", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-pya-0291", "section": "service", "who": "choir", "text": "Богородицы подобны:"},
  {"id": "cu-pya-0292", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-pya-0293", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0294", "section": "service", "who": "choir", "text": "[Υ] Во́ды вся превосхо́дит, Отрокови́це Чи́стая, / исто́чника Твоего́ вода́, / я́ве да́рующая свобожде́ние неду́гов лю́тых, / и душа́м вся́кое здра́вие, / я́ко па́че естества́ излива́емая."},
  {"id": "cu-pya-0295", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pya-0296", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0297", "section": "service", "who": "choir", "text": "[Υ] Во́ды вся превосхо́дит, Отрокови́це Чи́стая, / исто́чника Твоего́ вода́, / я́ве да́рующая свобожде́ние неду́гов лю́тых, / и душа́м вся́кое здра́вие, / я́ко па́че естества́ излива́емая."},
  {"id": "cu-pya-0298", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pya-0299", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0300", "section": "service", "who": "choir", "text": "[Λ] Реши́тель неду́гов но́вый се Силоа́м, / исто́чника Твоего́, Де́во, зрим вси: / о́чи бо прие́млет огня́, / вси же здра́вие при́сно к животу́ прие́млем."},
  {"id": "cu-pya-0301", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pya-0302", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0303", "section": "service", "who": "choir", "text": "[Ο] Здра́вия и́щущии притецы́те ко исто́чнику; / Отрокови́ца бо Де́ва жи́тельствует при воде́. / Лику́й и весели́ся ве́рных мно́жество / си́це, я́коже подоба́ет, / и́же бо прии́дет к хра́му, / воздая́ние проше́ний прие́млет."},
  {"id": "cu-pya-0304", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-pya-0305", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0306", "section": "service", "who": "choir", "text": "[Υ] Возвы́сися исто́чника Твоего́ вода́ вы́ше небе́с, / и земли́ бе́здны то́ки претече́; / сия́ есть пи́ща души́, питие́ ве́рных, / мед из ка́мене, и ма́нны раздая́ние."},
  {"id": "cu-pya-0307", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-pya-0308", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-pya-0309", "section": "service", "who": "choir", "text": "[Ε] Весели́ши Де́во царя́ преесте́ственне, / источа́ющи благода́ть от исто́чника присносу́щную, / сему́ подава́ющи на враги́ кре́пость, побе́ды при́сно, / здра́вие и мир, и проше́ний исполне́ние."},
  {"id": "cu-pya-0310", "section": "service", "who": "rubric", "text": "Таже оба лика, сошедшеся вкупе, поют припев:"},
  {"id": "cu-pya-0311", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца. И ирмос:"},
  {"id": "cu-pya-0312", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́. И тропарь:"},
  {"id": "cu-pya-0313", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0314", "section": "service", "who": "rubric", "text": "трижды. И ектениа."},
  {"id": "cu-pya-0315", "section": "service", "who": "choir", "text": "Ексапостиларий. Самогласен:"},
  {"id": "cu-pya-0316", "section": "service", "who": "choir", "text": "Пло́тию усну́в, / я́ко мертв, / Царю́ и Го́споди, / тридне́вен воскре́сл еси́, / Ада́ма воздви́г от тли, / и упраздни́в смерть, / Па́сха нетле́ния, / ми́ра спасе́ние. [Трижды.]"},
  {"id": "cu-pya-0317", "section": "service", "who": "choir", "text": "И источнику. Подобен:"},
  {"id": "cu-pya-0318", "section": "service", "who": "choir", "text": "Исто́чник еси́ вои́стинну воды́ живы́я, Влады́чице, / измыва́еши у́бо неду́ги душ и теле́с лю́тыя, / прикоснове́нием Твои́м еди́ным то́кмо, / во́ду спасе́ния Христа́ излива́ющи."},
  {"id": "cu-pya-0319", "section": "service", "who": "choir", "text": "На хвалитех, Всякое дыхание: поставим стихов 8, И поем стихиры воскресны осмогласника 4, глас 6: Стих:"},
  {"id": "cu-pya-0320", "section": "service", "who": "choir", "text": "Сотвори́ти отмще́ние во язы́цех, обличе́ния в лю́дех."},
  {"id": "cu-pya-0321", "section": "service", "who": "choir", "text": "Крест Твой, Го́споди, / жизнь и воскресе́ние лю́дем Твои́м есть, / и наде́ющеся нань, / Тебе́ воскре́сшаго Бо́га на́шего пое́м: поми́луй нас. Стих:"},
  {"id": "cu-pya-0322", "section": "service", "who": "choir", "text": "Связа́ти цари́ их пу́ты, и сла́вныя их ручны́ми око́вы желе́зными."},
  {"id": "cu-pya-0323", "section": "service", "who": "choir", "text": "Погребе́ние Твое́, Влады́ко, / рай отве́рзе ро́ду челове́ческому: / и от истле́ния изба́вльшеся, / Тебе́ воскре́сшаго Бо́га на́шего пое́м: поми́луй нас. Стих:"},
  {"id": "cu-pya-0324", "section": "service", "who": "choir", "text": "Сотвори́ти в них суд напи́сан: / сла́ва сия́ бу́дет всем преподо́бным Его́."},
  {"id": "cu-pya-0325", "section": "service", "who": "choir", "text": "Со Отце́м и Ду́хом Христа́ воспои́м, / воскре́сшаго из ме́ртвых, / и к Нему́ вопии́м: / Ты Живо́т еси́ наш и Воскресе́ние, поми́луй нас. Стих:"},
  {"id": "cu-pya-0326", "section": "service", "who": "choir", "text": "Хвали́те Бо́га во святы́х Его́, / хвали́те Его́ в утверже́нии си́лы Его́."},
  {"id": "cu-pya-0327", "section": "service", "who": "choir", "text": "Тридне́вен воскре́сл еси́, Христе, от гро́ба / я́коже пи́сано есть, / совоздви́гнувый пра́отца на́шего. / Те́мже Тя и сла́вит род челове́ческий, / и воспева́ет Твое́ воскресе́ние."},
  {"id": "cu-pya-0328", "section": "service", "who": "choir", "text": "И Богородицы стихиры, глас 2. Подобен: До́ме Евфра́фов: Стих:"},
  {"id": "cu-pya-0329", "section": "service", "who": "choir", "text": "Хвали́те Его́ на си́лах Его́, / хвали́те Его́ по мно́жеству вели́чествия Его́."},
  {"id": "cu-pya-0330", "section": "service", "who": "choir", "text": "Вода́ исто́чника, спаси́тельная есть / всем немощству́ющим; / присту́пим ве́рою, благода́ть почерпе́м. Стих:"},
  {"id": "cu-pya-0331", "section": "service", "who": "choir", "text": "Хвали́те Его́ во гла́се тру́бнем, / хвалите Его́ во псалти́ри и гу́слех."},
  {"id": "cu-pya-0332", "section": "service", "who": "choir", "text": "Кла́дязь живото́чный исто́чника безсме́ртнаго, / приступа́ющим любо́вию, исцеле́ний подае́т / излия́ние неисчерпа́емое. Стих:"},
  {"id": "cu-pya-0333", "section": "service", "who": "choir", "text": "Хвали́те Его́ в тимпа́не и ли́це, / хвали́те Его́ во стру́нах и орга́не."},
  {"id": "cu-pya-0334", "section": "service", "who": "choir", "text": "Укрепля́ет ду́ши вода́ Де́выя, / и́же в скве́рнах страсте́й, / притеце́м ко Отрокови́це, и сия́ измы́ем. Стих:"},
  {"id": "cu-pya-0335", "section": "service", "who": "choir", "text": "Хвали́те Его́ в кимва́лех доброгла́сных, хвали́те Его́ в кимва́лех восклица́ния, / вся́кое дыха́ние да хва́лит Го́спода."},
  {"id": "cu-pya-0336", "section": "service", "who": "choir", "text": "Ру́чка свяще́нная, и ма́нна незави́стная / из пречи́стыя утро́бы, излива́ет Влады́ку, / потре́бу вся́ческую поче́рпем."},
  {"id": "cu-pya-0337", "section": "service", "who": "choir", "text": "И стихиры Пасхи с припевы их, глас 5. Стих:"},
  {"id": "cu-pya-0338", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-pya-0339", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-pya-0340", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-pya-0341", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-pya-0342", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-pya-0343", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-pya-0344", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-pya-0345", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-pya-0346", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0347", "section": "service", "who": "choir", "text": "Таже настоящий тропарь, во глас 5, трижды:"},
  {"id": "cu-pya-0348", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0349", "section": "service", "who": "choir", "text": "И ектении, и отпуст. И час 1-й. Творим же и литию вне обители."},
  {"id": "cu-pya-0350", "section": "service", "who": "rubric", "text": "Подобает ведати, я́ко творим исхождение днесь вне монастыря, предносяще хоругви. В руках же держаще святое Евангелие, честный Крест, и иконы Воскресе́ния Христо́ва, Пречистыя Богоро́дицы. Поем канон Пасхи с Богородичны, на 8. И Катавасия, ирмос тойже. По 6-й песни, последи Евангелиа глаголем:"},
  {"id": "cu-pya-0351", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше:"},
  {"id": "cu-pya-0352", "section": "service", "who": "rubric", "text": "трижды. Таже, стихира:"},
  {"id": "cu-pya-0353", "section": "service", "who": "choir", "text": "Воскрес Иису́с от гро́ба:"},
  {"id": "cu-pya-0354", "section": "service", "who": "rubric", "text": "трижды. Таже, 7-я, 8-я и 9-я песни. И прочее молебна."},
  {"id": "cu-pya-0355", "section": "service", "who": "choir", "text": "Часы Пасхи."},
  {"id": "cu-pya-0356", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-pya-0357", "section": "service", "who": "rubric", "text": "Наченшу диакону:"},
  {"id": "cu-pya-0358", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко."},
  {"id": "cu-pya-0359", "section": "service", "who": "rubric", "text": "Настоятелю же возгласившу:"},
  {"id": "cu-pya-0360", "section": "service", "who": "deacon", "text": "Благослове́но Ца́рство Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-pya-0361", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-pya-0362", "section": "service", "who": "deacon", "text": "Настоятель поет с прочими служители во святом олтаре:"},
  {"id": "cu-pya-0363", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-pya-0364", "section": "service", "who": "deacon", "text": "И лики тойжде, трижды."},
  {"id": "cu-pya-0365", "section": "service", "who": "choir", "text": "Настоятель глаголет припевы: Первый стих:"},
  {"id": "cu-pya-0366", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-pya-0367", "section": "service", "who": "choir", "text": "И на кийждо стих мы поем тропарь весь по единожды: Тропарь:"},
  {"id": "cu-pya-0368", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Вторый стих:"},
  {"id": "cu-pya-0369", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pya-0370", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-pya-0371", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-pya-0372", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0373", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-pya-0374", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-pya-0375", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0376", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-pya-0377", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0378", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-pya-0379", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-pya-0380", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-pya-0381", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. Мы же:"},
  {"id": "cu-pya-0382", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0383", "section": "service", "who": "choir", "text": "Посем глаголет диакон ектению великую. По ектении же и по возгласе:"},
  {"id": "cu-pya-0384", "section": "service", "who": "choir", "text": "Антифон первый, псалом 65, глас 2. Стих 1:"},
  {"id": "cu-pya-0385", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви / вся земля́. Припев:"},
  {"id": "cu-pya-0386", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pya-0387", "section": "service", "who": "rubric", "text": "И другий лик тойжде стих:"},
  {"id": "cu-pya-0388", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви вся земля́, / по́йте же и́мени Его́, дади́те сла́ву хвале́ Его́. Припев:"},
  {"id": "cu-pya-0389", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 2:"},
  {"id": "cu-pya-0390", "section": "service", "who": "choir", "text": "Рцы́те Бо́гу: коль стра́шна дела́ Твоя́, / во мно́жестве си́лы Твоея́ со́лжут Тебе́ врази́ Твои́. Припев:"},
  {"id": "cu-pya-0391", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 3:"},
  {"id": "cu-pya-0392", "section": "service", "who": "choir", "text": "Вся земля́ да покло́нится Тебе́, / и пое́т Тебе́, да пое́т же и́мени Твоему́ Вы́шний. Припев:"},
  {"id": "cu-pya-0393", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pya-0394", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-pya-0395", "section": "service", "who": "rubric", "text": "Купно оба лика вышшим гласом:"},
  {"id": "cu-pya-0396", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-pya-0397", "section": "service", "who": "choir", "text": "Таже, ектениа малая."},
  {"id": "cu-pya-0398", "section": "service", "who": "choir", "text": "Антифон вторый, псалом 66, глас тойже. Стих 1:"},
  {"id": "cu-pya-0399", "section": "service", "who": "choir", "text": "Бо́же уще́дри ны / и благослови́ ны. Припев:"},
  {"id": "cu-pya-0400", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-pya-0401", "section": "service", "who": "rubric", "text": "Другая страна, тойже стих:"},
  {"id": "cu-pya-0402", "section": "service", "who": "choir", "text": "Бо́же, уще́дри ны и благослови́ ны, / просвети лице Твое́ на ны и поми́луй ны. Припев:"},
  {"id": "cu-pya-0403", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 2:"},
  {"id": "cu-pya-0404", "section": "service", "who": "choir", "text": "Да позна́ем на земли́ путь Твой, / во всех язы́цех спасе́ние Твое́. Припев:"},
  {"id": "cu-pya-0405", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 3:"},
  {"id": "cu-pya-0406", "section": "service", "who": "choir", "text": "Да испове́дятся Тебе́ лю́дие, Бо́же, / да испове́дятся Тебе́ лю́дие вси. Припев:"},
  {"id": "cu-pya-0407", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-pya-0408", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-pya-0409", "section": "service", "who": "rubric", "text": "Вкупе два лика:"},
  {"id": "cu-pya-0410", "section": "service", "who": "choir", "text": "Единоро́дный Сы́не и Сло́ве Бо́жий, Безсме́ртен Сый / и изво́ливый спасе́ния на́шего ра́ди / воплоти́тися от Святы́я Богоро́дицы и Присноде́вы Мари́и, / непрело́жно вочелове́чивыйся, / распны́йся же, Христе́ Бо́же, сме́ртию смерть попра́вый, / Еди́н Сый Святы́я Тро́ицы, / спрославля́емый Отцу́ и Свято́му Ду́ху, спаси́ нас."},
  {"id": "cu-pya-0411", "section": "service", "who": "choir", "text": "Таже, ектениа."},
  {"id": "cu-pya-0412", "section": "service", "who": "choir", "text": "Антифон 3-й, псалом 67, глас 5. Стих 1:"},
  {"id": "cu-pya-0413", "section": "service", "who": "choir", "text": "Да воскре́снет Бог / и расточа́тся врази́ Его́."},
  {"id": "cu-pya-0414", "section": "service", "who": "choir", "text": "Тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0415", "section": "service", "who": "rubric", "text": "Другая страна, той же стих:"},
  {"id": "cu-pya-0416", "section": "service", "who": "choir", "text": "Да воскре́снет Бог и расточа́тся врази́ Его́, / и да бежа́т от лица́ Его́ ненави́дящии Его́. Тропарь:"},
  {"id": "cu-pya-0417", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 2:"},
  {"id": "cu-pya-0418", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-pya-0419", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 3:"},
  {"id": "cu-pya-0420", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от лица́ Бо́жия, / а пра́ведницы да возвеселя́тся, да возра́дуются пред Бо́гом. Тропарь:"},
  {"id": "cu-pya-0421", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0422", "section": "service", "who": "rubric", "text": "И бывает вход. И возглашает диакон, аще есть, аще же ни, иерей:"},
  {"id": "cu-pya-0423", "section": "service", "who": "deacon", "text": "Прему́дрость, про́сти."},
  {"id": "cu-pya-0424", "section": "service", "who": "deacon", "text": "Мы же входное: В це́рквах благослови́те Бо́га, / Го́спода от исто́чник Изра́илевых."},
  {"id": "cu-pya-0425", "section": "service", "who": "deacon", "text": "И поем тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0426", "section": "service", "who": "deacon", "text": "Ипакои, глас 4: Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-pya-0427", "section": "service", "who": "deacon", "text": "Слава, кондак Богородицы, глас 8. Подобен: Взбра́нной: От неистощи́мыя Ты, исто́чниче богоблагода́тный, / подае́ши ми, точа́щи во́ды Твоея́ благода́ти, / приснотеку́щий па́че сло́ва, / я́ко бо Сло́во ро́ждшая па́че смы́сла, / молю́ Ти ся, ороси́ мя благода́тию, да зову́ Ти: / ра́дуйся, водо́ спаси́тельная."},
  {"id": "cu-pya-0428", "section": "service", "who": "deacon", "text": "И ныне: кондак Пасце, глас 8: А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-pya-0429", "section": "service", "who": "deacon", "text": "Вместо же Трисвятаго: Ели́цы во Христа́ крести́стеся, / во Христа́ облеко́стеся: / аллилу́иа."},
  {"id": "cu-pya-0430", "section": "service", "who": "deacon", "text": "Прокимен, глас 8: Во всю зе́млю изы́де веща́ние их, / и в концы́ вселе́нныя глаго́лы их. Стих:"},
  {"id": "cu-pya-0431", "section": "service", "who": "deacon", "text": "Небеса́ пове́дают сла́ву Бо́жию, творе́ние же руку́ Его́ возвеща́ет твердь."},
  {"id": "cu-pya-0432", "section": "service", "who": "deacon", "text": "И прокимен, глас 3, песнь Богородицы: Вели́чит душа́ Моя́ Го́спода, и возра́довася дух Мой о Бо́зе, Спа́се Мое́м."},
  {"id": "cu-pya-0433", "section": "service", "who": "deacon", "text": "Деяния святых Апостол, зачало 7."},
  {"id": "cu-pya-0434", "section": "service", "who": "deacon", "text": "Во дни о́ны, вку́пе Петр и Иоа́нн восхожда́ста во святи́лище на моли́тву в час девя́тый. И не́кий муж, хром от чре́ва ма́тере своея́ сый, носи́мь быва́ше, его́же полага́ху по вся дни пред две́рьми церко́вными, реко́мыми Кра́сными, проси́ти ми́лостыни от входя́щих в це́рковь. И́же ви́дев Петра́ и Иоа́нна хотя́щыя вни́ти в це́рковь, проша́ше ми́лостыни. Воззре́в же Петр нань со Иоа́нном, рече́: воззри́ на ны. Он же прилежа́ше и́ма, мня не́что от нею́ прия́ти. Рече́ же Петр: сребра́ и зла́та несть у мене́, но е́же и́мам, сие́ ти даю́, во и́мя Иису́са Христа́ Назоре́а воста́ни и ходи́. И емь его́ за десну́ю ру́ку воздви́же, а́бие же утверди́стеся его́ плесне́ и гле́зне, и вскочи́в ста и хожда́ше, и вни́де с ни́ма в це́рковь, ходя́ и скачя́ и хваля́ Бо́га."},
  {"id": "cu-pya-0435", "section": "service", "who": "deacon", "text": "И Богородицы, Послание к филипписием, зачало 240."},
  {"id": "cu-pya-0436", "section": "service", "who": "deacon", "text": "Бра́тие, сие́ да му́дрствуется в вас, е́же и во Христе́ Иису́се, И́же во о́бразе Бо́жии сый, не восхище́нием непщева́ бы́ти ра́вен Бо́гу. Но Себе́ ума́лил, зрак раба́ прии́м, в подо́бии челове́честем быв, и о́бразом обре́теся я́коже челове́к. Смири́л Себе́, послушли́в быв да́же до сме́рти, сме́рти же кре́стныя. Те́мже и Бог Его́ превознесе́ и дарова́ Ему́ и́мя, е́же па́че вся́каго и́мене, да о и́мени Иису́сове вся́ко коле́но поклони́тся небе́сных и земны́х и преиспо́дних, и всяк язы́к испове́сть, я́ко Госпо́дь Иису́с Христо́с в сла́ву Бо́га Отца́."},
  {"id": "cu-pya-0437", "section": "service", "who": "deacon", "text": "Аллилуиа, глас 1: Стих:"},
  {"id": "cu-pya-0438", "section": "service", "who": "deacon", "text": "Испове́дят небеса́ чудеса́ Твоя́, Го́споди. Стих:"},
  {"id": "cu-pya-0439", "section": "service", "who": "deacon", "text": "Бог прославля́емь в сове́те святы́х. Стих:"},
  {"id": "cu-pya-0440", "section": "service", "who": "deacon", "text": "Слы́ши, Дщи, и виждь, и приклони́ у́хо Твое́."},
  {"id": "cu-pya-0441", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 7."},
  {"id": "cu-pya-0442", "section": "service", "who": "deacon", "text": "Во вре́мя о́но, сни́де Иису́с в Капернау́м Сам и Ма́ти Его́, и бра́тия Его́ и ученицы́ Его́, и ту не мно́ги дни пребы́ша. И близ бе Па́сха иуде́йска, и взы́де во Иерусали́м Иису́с и обре́те в це́ркви продаю́щыя о́вцы и волы́ и го́луби, и пе́няжники седя́щыя. И сотвори́ бичь от ве́рвий, вся изгна́ из це́ркве, о́вцы и волы́, и торжнико́м разсы́па пе́нязи и дски опрове́рже. И продаю́щым го́луби рече́: возьми́те сия́ отсю́ду и не твори́те до́му Отца́ Моего́ до́му ку́пленаго. Помяну́ша же ученицы́ Его́, я́ко пи́сано есть: жа́лость до́му Твоего́ снесть Мя. Отвеща́ша же иуде́е и ре́ша Ему́: ко́е зна́мение явля́еши нам, я́ко сия́ твори́ши? Отвеща́ Иису́с и рече́ им: разорите́ це́рковь сию́, и тре́ми де́ньми воздви́гну ю́. Ре́ша же иуде́е: четы́редесять и шестию́ лет создана́ бысть це́рковь сия́, и Ты ли тре́ми де́ньми воздви́гнеши ю́? Он же глаго́лаше о це́ркви те́ла Своего́. Егда́ у́бо воста́ от ме́ртвых, помяну́ша ученицы́ Его́, я́ко се глаго́лаше, и ве́роваша Писа́нию и словеси́, е́же рече́ Иису́с."},
  {"id": "cu-pya-0443", "section": "service", "who": "deacon", "text": "И Богородицы, Евангелие от Луки, зачало 54."},
  {"id": "cu-pya-0444", "section": "service", "who": "deacon", "text": "Во вре́мя о́но, вни́де Иису́с в весь не́кую, жена́ же не́кая и́менем Ма́рфа прия́т Его́ в дом свой. И сестра́ ей бе нарица́емая Мари́а, я́же и се́дши при ногу́ Иису́сову, слы́шаше сло́во Его́. Ма́рфа же мо́лвяше о мно́зе слу́жбе, ста́вши же рече́: Го́споди, не бреже́ши ли, я́ко сестра́ моя́ еди́ну мя оста́ви служи́ти; рцы у́бо ей, да ми помо́жет. Отвеща́в же Иису́с, рече́ ей: Ма́рфо, Ма́рфо, пече́шися и мо́лвиши о мно́зе. Еди́но же есть на потре́бу. Мари́а же благу́ю часть избра́, я́же не оты́мется от нея́. Бысть же егда́ глаго́лаше сия́, воздви́гши не́кая жена́ глас от наро́да, рече́ Ему́: блаже́но чре́во носи́вшее Тя, и сосца́, я́же еси́ ссал. Он же рече́: те́мже у́бо блаже́ни слы́шащии сло́во Бо́жие, и храня́ще е́."},
  {"id": "cu-pya-0445", "section": "service", "who": "deacon", "text": "И бывает по чину Божественная Литургиа Златоустаго."},
  {"id": "cu-pya-0446", "section": "service", "who": "deacon", "text": "Вместо же Достойно: поем: А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся."},
  {"id": "cu-pya-0447", "section": "service", "who": "rubric", "text": "Таже ирмос, глас 1:"},
  {"id": "cu-pya-0448", "section": "service", "who": "deacon", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-pya-0449", "section": "service", "who": "deacon", "text": "Причастный: Те́ло Христо́во приими́те, / исто́чника безсме́ртнаго вкуси́те. И Богородице:"},
  {"id": "cu-pya-0450", "section": "service", "who": "deacon", "text": "Ча́шу спасе́ния прииму́, / и и́мя Госпо́дне призову́. / Аллилу́иа, трижды."},
  {"id": "cu-pya-0451", "section": "service", "who": "rubric", "text": "Егда же настоятель глаголет:"},
  {"id": "cu-pya-0452", "section": "service", "who": "deacon", "text": "Со стра́хом Бо́жиим и ве́рою приступи́те."},
  {"id": "cu-pya-0453", "section": "service", "who": "rubric", "text": "Мы вместо, Благословен грядый во имя Господне: поем:"},
  {"id": "cu-pya-0454", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0455", "section": "service", "who": "rubric", "text": "единожды. Настоятель глаголет:"},
  {"id": "cu-pya-0456", "section": "service", "who": "deacon", "text": "Спаси́ Бо́же лю́ди Твоя́: И мы:"},
  {"id": "cu-pya-0457", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0458", "section": "service", "who": "rubric", "text": "единожды. Егда же изглаголет иерей:"},
  {"id": "cu-pya-0459", "section": "service", "who": "priest", "text": "Всегда́ ны́не и при́сно: И мы:"},
  {"id": "cu-pya-0460", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0461", "section": "service", "who": "rubric", "text": "единожды. Посем ектениа. Вместо же, Буди имя Господне: и вместо псалма, Благословлю Господа: поем:"},
  {"id": "cu-pya-0462", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-pya-0463", "section": "service", "who": "rubric", "text": "дванадесять, и множае: дондеже анафора от игумена раздастся. Таже настоятель,"},
  {"id": "cu-pya-0464", "section": "service", "who": "priest", "text": "Благослове́ние Госпо́дне на вас:"},
  {"id": "cu-pya-0465", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-pya-0466", "section": "service", "who": "rubric", "text": "Посем настоятель вместо, Слава Тебе Христе Боже: поет:"},
  {"id": "cu-pya-0467", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-pya-0468", "section": "service", "who": "rubric", "text": "И лик:"},
  {"id": "cu-pya-0469", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-pya-0470", "section": "service", "who": "rubric", "text": "Посем настоятель глаголет отпуст со Крестом по обычаю."},
];

